def solve(a, b=None, *args, **kwargs):
    # handle different calling conventions
    if b is None:
        # maybe solve([a,b]) or solve((a,b))
        if isinstance(a, (list, tuple)) and len(a) == 2 and all(isinstance(x, str) for x in a):
            a, b = a[0], a[1]
        elif args:
            # solve(a, b) passed oddly? shouldn't happen
            b = args[0] if args else ""
        else:
            b = ""
    if a is None:
        a = ""
    if b is None:
        b = ""
    # coerce bytes
    if isinstance(a, (bytes, bytearray)):
        try:
            a = a.decode()
        except Exception:
            a = str(a)
    if isinstance(b, (bytes, bytearray)):
        try:
            b = b.decode()
        except Exception:
            b = str(b)
    a = str(a)
    b = str(b)
    m, n = len(a), len(b)
    if m == 0:
        return n
    if n == 0:
        return m
    # ensure n smaller for memory
    prev = list(range(n+1))
    for i in range(1, m+1):
        cur = [i] + [0]*n
        ai = a[i-1]
        for j in range(1, n+1):
            cost = 0 if ai == b[j-1] else 1
            cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
        prev = cur
    return prev[n]

